fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Calculate the difference safely using i16 to avoid overflow
    let diff = (a as i16).wrapping_sub(b as i16);
    
    // Check if the absolute difference is strictly less than tolerance
    diff.abs() < (tol as i16)
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // The problem states arrays have equal, non-zero length
    // and tolerance is strictly positive, so we can proceed directly
    
    let mut result = Vec::with_capacity(a.len());
    
    for i in 0..a.len() {
        result.push(is_close_i8(a[i], b[i], tol));
    }
    
    result
}